 let rules=recipe(),projectType='strategy',conversionSource=null,mode='build',editor='visual',cursor=0,dirty=true,touched=false,assumptionsDirty=false,busy=false,playing=null,selectedEvent=null,generation=0;
 const pending=new Map();
