 function validRunConfig(){const c=activeConfig();return projectType==='analysis'?!!c.start&&!!c.end:!!c.start&&!!c.end&&!!c.reserved_start&&[c.capital,c.allocation_pct,c.fee_bps,c.fixed_fee,c.slippage_bps].every(Number.isFinite);}
 function stale(){return dirty||assumptionsDirty||!run||run.version!==version?.id||canonical(run.result.specification??run.result.strategy)!==canonical(activeSpecification())||canonical(run.result.config)!==canonical(activeConfig());}
 function changed(){editSequence++;dirty=true;touched=true;pause();saveState();}
